#!/usr/bin/env bash
# AET-WO-1313b: no-bound bytes. Every specification in the corpus without a declared bound
# (examples and every fixture with a board and an mcu), emitted and generated by main's binary
# (A) and by the scratch binary (B) under AET_1313B=<letters> ("-" for unset); output paths
# normalised. Usage: spike/1313b/corpus.sh <binA> <binB> <letters> <repo-root>
set -u
A=$1; B=$2; L=$3; ROOT=$4; M=$L; [ "$L" = - ] && M=
O=$(mktemp -d); mkdir -p "$O/A" "$O/B"
n=0; same=0; differ=""
cd "$ROOT"
for f in $(grep -rlE '"schema_version": *15,' --include=*.json examples crates | sort); do
  python3 -I -c 'import json,sys; d=json.load(open(sys.argv[1])); sys.exit(0 if isinstance(d,dict) and "board" in d and "mcu" in d and "max_outline_um" not in d["board"] else 1)' "$f" || continue
  k=$(echo "$f" | tr '/' '_')
  "$A" emit --file "$f" --out "$O/A/$k/e" > "$O/A/$k.e.json" 2>/dev/null || true
  "$A" generate --spec "$f" --out "$O/A/$k/g" > "$O/A/$k.g.json" 2>/dev/null || true
  AET_1313B=$M "$B" emit --file "$f" --out "$O/B/$k/e" > "$O/B/$k.e.json" 2>/dev/null || true
  AET_1313B=$M "$B" generate --spec "$f" --out "$O/B/$k/g" > "$O/B/$k.g.json" 2>/dev/null || true
  sed -i "s#$O/A/#X/#g" "$O/A/$k.e.json" "$O/A/$k.g.json"; sed -i "s#$O/B/#X/#g" "$O/B/$k.e.json" "$O/B/$k.g.json"
  n=$((n+1))
  dirs_same() { if [ -e "$O/A/$k" ] || [ -e "$O/B/$k" ]; then diff -rq "$O/A/$k" "$O/B/$k" >/dev/null; fi; }
  if dirs_same && cmp -s "$O/A/$k.e.json" "$O/B/$k.e.json" && cmp -s "$O/A/$k.g.json" "$O/B/$k.g.json"; then same=$((same+1)); else differ="$differ $f"; fi
done
echo "letters=$L specs $n byte-identical $same files $(find "$O/B" -type f | wc -l)${differ:+ | differ:$differ}"
